"""Basic 10–11 course: explicit applicability, distinct topic sequence, shared canonical exercises."""
from copy import deepcopy
from bank_tools import H,G,P,ORACLES
byid={t['id']:t for t in bank}
for t in bank:
    t.setdefault('level','advanced' if t['grade']>=10 else 'basic')
    for q in t['tasks']:q.setdefault('canonicalId',q['id'])
def pick(tid,*indices):
    ts=byid[tid]['tasks'];return [ts[i-1] if i>0 else next(q for q in ts if q.get('challenge')) for i in indices]
def new(prompt,answer,solution,oracle):
    value,display=answer if isinstance(answer,tuple) else (answer,str(answer))
    return dict(prompt=prompt,answer=value,display=display,solution=solution,kind='set' if isinstance(value,list) else 'number',_oracle=oracle)
def B(g,num,subject,title,ref,questions,challenge):
    tid=f'{g}-{100+num:02}';tasks=[]
    for i,src in enumerate(questions+[challenge],1):
        q=deepcopy(src);original=q.get('canonicalId',q.get('id'))
        q['id']=f'{tid}-{i}';q['canonicalId']=original or q['id']
        if i==5:q.update(difficulty='Суперсложный',tricky=True,challenge=True)
        else:q['difficulty']=['Базовый','Средний','Средний','Повышенный'][i-1]
        ORACLES[q['id']]=q.pop('_oracle',None) or ORACLES[original]
        tasks.append(q)
    bank.append(dict(id=tid,grade=g,level='basic',course=subject,subject=subject,title=title,ref=ref,tasks=tasks))
