# Applicability lists expose intentional sharing, without counting copies as distinct authored tasks.
applicability={}
for t in bank:
    for q in t['tasks']:
        applicability.setdefault(q['canonicalId'],[]).append({'grade':t['grade'],'level':t['level'],'topic':t['id']})
for t in bank:
    for q in t['tasks']:q['applicability']=applicability[q['canonicalId']]
